"=== CLI tools ==="; foreach ($c in 'claude','codex','opencode','node','npm','git','bun','pwsh','rg') { $g = Get-Command $c -ErrorAction SilentlyContinue; if ($g) { "{0,-10} {1}" -f $c, $g.Source } else { "{0,-10} NOT FOUND" -f $c } }
"=== node/npm/claude versions ==="; try { "node $(node -v)" } catch {}; try { "claude $(claude --version)" } catch {}
"=== Orca exe ==="; Get-ChildItem "$env:LOCALAPPDATA\Orca" -Recurse -Filter '*.exe' -Depth 2 -ErrorAction SilentlyContinue | Select-Object FullName, Length | Format-Table -AutoSize

