"=== Orca.exe locations ==="; @("$env:LOCALAPPDATA\Programs","C:\Program Files","C:\Program Files (x86)") | ForEach-Object { Get-ChildItem $_ -Directory -ErrorAction SilentlyContinue | Where-Object Name -like '*rca*' | Select-Object -ExpandProperty FullName }
Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue | Where-Object DisplayName -like '*Orca*' | Format-List DisplayName,DisplayVersion,InstallLocation,DisplayIcon,UninstallString,Publisher
"=== running? ==="; Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -like '*orca*' -or $_.ProcessName -like '*claude*' } | Select-Object Id, ProcessName, Path | Format-Table -AutoSize

foreach ($d in 'agents','commands','skills','plugins','output-styles') { $p = "$env:USERPROFILE\.claude\$d"; if (Test-Path $p) { "=== $d ==="; Get-ChildItem $p -Recurse -Force -Depth 2 -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName } else { "=== $d : MISSING ===" } }
"=== CLAUDE.md ==="; if (Test-Path "$env:USERPROFILE\.claude\CLAUDE.md") { "exists" } else { "MISSING" }
"=== .local\bin ==="; Get-ChildItem "$env:USERPROFILE\.local\bin" -ErrorAction SilentlyContinue | Select-Object Name | Format-Table -AutoSize
"=== PATH has .local\bin? ==="; ($env:PATH -split ';' | Where-Object { $_ -like '*local*bin*' })

"=== Orca resources\bin ==="; Get-ChildItem "$env:LOCALAPPDATA\Programs\orca\resources\bin" -ErrorAction SilentlyContinue | Select-Object Name, Length | Format-Table -AutoSize
"=== git anywhere? ==="; @("C:\Program Files\Git\cmd\git.exe","C:\Program Files (x86)\Git\cmd\git.exe","$env:LOCALAPPDATA\Programs\Git\cmd\git.exe") | ForEach-Object { "{0} -> {1}" -f $_, (Test-Path $_) }
"=== winget ==="; $w = Get-Command winget -ErrorAction SilentlyContinue; if ($w) { "winget -> $($w.Source)" } else { "winget NOT FOUND" }
"=== workspaceDir exists? ==="; Test-Path "$env:USERPROFILE\orca\workspaces"

